// The pair's textures and materials (handdrums.md 4.2 with review item 14's fixes), all generated by our code (ProcTex
// noise; no third-party images), baked by Tools/unity.sh bake through HandDrumsTextureProvider (names "HandDrums/<name>"),
// generated at runtime when unbaked. Calm and real: lacquered ash, cream rawhide, chrome; nothing glows, no emission.
//  - staves (512 x 1024, one stave wide, along the stave): ash with straight grain lines, the joint seam drawn in at u 0 / 1
//  - rawhide (1024 x 1024) + rawhide_n (normal): fibre mottling, a few translucent-looking darker blotches, a faint spine
//    line, the darker smoother band where the hide wraps the bearing edge, hand wear (the near edge and the centre)
//  - hardware (64 x 16 atlas) + hardware_mg (metallic R, smoothness A): chrome, steel, satin black (legs), rubber (feet)
// Three draws: shells, heads, hardware (templates "HandDrums/Shell", "HandDrums/Rawhide", "HandDrums/Hardware").
using System;
using System.Collections.Generic;
using MusicRoom.Core;
using UnityEngine;

namespace MusicRoom.HandDrums
{
    public static class HandDrumsTextures
    {
        public const string Staves = "HandDrums/staves", Rawhide = "HandDrums/rawhide", RawhideN = "HandDrums/rawhide_n";
        public const string Hardware = "HandDrums/hardware", HardwareMg = "HandDrums/hardware_mg";
        public const int StaveW = 512, StaveH = 1024, HideSize = 1024;

        static double Smooth(double a, double b, double x) { double t = Math.Max(0, Math.Min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); }
        static Color32 C(double r, double g, double b, double a = 1) => new Color32(ProcTex.ClampByte(r * 255), ProcTex.ClampByte(g * 255), ProcTex.ClampByte(b * 255), ProcTex.ClampByte(a * 255));

        /// <summary>Lacquered ash, one stave: grain lines along v, gentle figure, the joint seam darker at u 0 and 1.</summary>
        public static Texture2D StavesMap()
        {
            int W = StaveW, H = StaveH;
            var px = new Color32[W * H];
            for (int y = 0; y < H; y++)
                for (int x = 0; x < W; x++)
                {
                    double u = (x + 0.5) / W, v = (y + 0.5) / H;
                    // straight ash grain: a few irregular ring lines across the stave, wandering slowly along it
                    double g = u * 6.5 + 1.1 * ProcTex.Fbm(u * 1.6 + 5, v * 1.1 + 2, 3) + 0.12 * Math.Sin(v * 7 + u * 2);
                    double f = g - Math.Floor(g);
                    double line = Smooth(0.0, 0.10, f) * (1 - Smooth(0.14, 0.42, f)) * (0.55 + 0.45 * ProcTex.VNoise(u * 4 + 3, v * 3));
                    double streak = ProcTex.VNoise(u * 110, v * 5) * 0.6 + ProcTex.VNoise(u * 260, v * 11) * 0.4;   // fine pores along the grain
                    double figure = ProcTex.Fbm(u * 2.2 + 11, v * 0.7 + 4, 3);                    // broad colour variation
                    double band = ProcTex.Fbm(u * 0.8 + 21, v * 0.25 + 9, 2);                     // long lighter / darker bands
                    double k = 0.84 + 0.16 * figure + 0.10 * (band - 0.5) - 0.10 * line - 0.05 * (streak - 0.5);
                    // the joint: a thin glue line and the slightly darker stave edges
                    double e = Math.Min(u, 1 - u) * W;
                    double seam = e < 1.2 ? 0.42 : e < 3.5 ? 0.42 + 0.4 * (e - 1.2) / 2.3 : e < 12 ? 0.82 + 0.18 * (e - 3.5) / 8.5 : 1;
                    k *= seam;
                    // warm amber satin lacquer over ash (#b07a45, a little less orange under the room's warm light)
                    double r = 0.64 * k + 0.03 * figure, gg = 0.45 * k + 0.01 * band, b = 0.27 * k * (0.94 + 0.08 * line);
                    px[y * W + x] = C(r, gg, b);
                }
            return ProcTex.Make(W, H, px, false, true, "staves");
        }

        static void HidePolar(double u, double v, out double rho, out double theta)
        {
            // the head mesh's uv disc: radius 0.5 at the end of the wrap, a + 9 mm (HandDrumsGeometry.Head); rho re the conga
            double uvR = HandDrumsDims.A[0] + HandDrumsDims.Wrap[HandDrumsDims.Wrap.Length - 1].x + 0.004;
            double lx = (u - 0.5) * 2 * uvR, lz = (v - 0.5) * 2 * uvR;
            rho = Math.Sqrt(lx * lx + lz * lz) / HandDrumsDims.A[0];
            theta = Math.Atan2(-lx, -lz);
        }

        /// <summary>The hide's height field (fibre, pores, blotch edges; smoother where hands wear it) and its tints.</summary>
        static void HideSample(double u, double v, out double height, out double r, out double g, out double b)
        {
            HidePolar(u, v, out double rho, out double th);
            double x = u * 7, y = v * 7;
            // fibres: fine noise, only slightly drawn out along a slowly turning direction (hide is felted, not brushed)
            double ang = 0.6 + 1.2 * ProcTex.Fbm(x * 0.4 + 9, y * 0.4 + 3, 2);
            double ca = Math.Cos(ang), sa = Math.Sin(ang);
            double fx = (x * ca + y * sa) * 34, fy = (-x * sa + y * ca) * 17;
            double fibre = ProcTex.VNoise(fx, fy) * 0.55 + ProcTex.VNoise(fx * 2.3 + 7, fy * 2.3) * 0.45;
            double mottle = ProcTex.Fbm(x * 2.6 + 1, y * 2.6 + 5, 3);
            double fine = ProcTex.Fbm(x * 12 + 3, y * 12 + 8, 2);
            // a few small translucent-looking darker patches (about 8 % of the hide) and thin darker veins
            double blotchN = ProcTex.Fbm(x * 1.7 + 13, y * 1.7 + 2, 3);
            double blotch = Smooth(0.64, 0.74, blotchN);
            double vein = Math.Exp(-Math.Pow((ProcTex.Fbm(x * 1.3 + 31, y * 1.3 + 17, 3) - 0.5) / 0.012, 2)) * 0.7;
            // a faint spine line across the hide (darker, slightly fibrous)
            double sd = Math.Abs((u - 0.5) * 0.82 + (v - 0.5) * 0.57 + 0.03 * Math.Sin(v * 11));
            double spine = Math.Exp(-sd * sd / (2 * 0.035 * 0.035)) * 0.6;
            // hand wear: the near edge (theta 0 +- 50 deg, rho .75 .. .97) and the centre (palm strokes)
            double dth = Math.Abs(Math.IEEERemainder(th, 2 * Math.PI));
            double edgeWear = Smooth(0.68, 0.82, rho) * (1 - Smooth(0.95, 1.0, rho)) * Math.Max(0, 1 - dth / 0.95);
            double centreWear = 1 - Smooth(0.15, 0.42, rho);
            double wear = Math.Max(edgeWear * 0.9, centreWear * 0.7) * (0.75 + 0.5 * mottle);
            // the wrap over the bearing edge: darker, smoother (stretched and handled)
            double wrap = Smooth(0.975, 1.02, rho);
            double rough = (1 - 0.55 * wear) * (1 - 0.7 * wrap);
            height = (fibre - 0.5) * 0.45 * rough + (fine - 0.5) * 0.35 * rough + blotch * 0.12 + vein * 0.10 + spine * 0.12;
            // cream-tan #d9c7a1 with mottling; blotches warmer and darker; wear a touch greyer and darker
            double k = 0.95 + 0.08 * (mottle - 0.5) + 0.04 * (fine - 0.5) - 0.05 * (fibre - 0.5) * rough;
            k *= 1 - 0.07 * blotch - 0.05 * vein - 0.06 * spine - 0.08 * wear - 0.20 * wrap;
            // cream-tan #d9c7a1, the patches a warmer, more translucent amber
            r = 0.87 * k; g = 0.78 * k * (1 - 0.035 * blotch); b = 0.60 * k * (1 - 0.12 * blotch - 0.05 * wear) + 0.012 * wear;
        }

        public static Texture2D RawhideMap()
        {
            int N = HideSize;
            var px = new Color32[N * N];
            for (int y = 0; y < N; y++)
                for (int x = 0; x < N; x++)
                {
                    HideSample((x + 0.5) / N, (y + 0.5) / N, out _, out double r, out double g, out double b);
                    px[y * N + x] = C(r, g, b);
                }
            return ProcTex.Make(N, N, px, false, true, "rawhide");
        }

        /// <summary>Tangent-space normals from the height field (rgb = n * 0.5 + 0.5, a = 1: reads as RGB or AG packed).</summary>
        public static Texture2D RawhideNormal()
        {
            int N = HideSize;
            var h = new float[N * N];
            for (int y = 0; y < N; y++) for (int x = 0; x < N; x++) { HideSample((x + 0.5) / N, (y + 0.5) / N, out double hh, out _, out _, out _); h[y * N + x] = (float)hh; }
            var px = new Color32[N * N];
            const double strength = 2.2;
            for (int y = 0; y < N; y++)
                for (int x = 0; x < N; x++)
                {
                    double dx = h[y * N + Math.Min(N - 1, x + 1)] - h[y * N + Math.Max(0, x - 1)];
                    double dy = h[Math.Min(N - 1, y + 1) * N + x] - h[Math.Max(0, y - 1) * N + x];
                    double nx = -dx * strength, ny = -dy * strength, nz = 1, l = Math.Sqrt(nx * nx + ny * ny + nz * nz);
                    px[y * N + x] = C(nx / l * 0.5 + 0.5, ny / l * 0.5 + 0.5, nz / l * 0.5 + 0.5, 1);
                }
            return ProcTex.Make(N, N, px, true, true, "rawhide_n");
        }

        // the atlas: four regions of 16 px across u (HandDrumsGeometry.Uv*)
        static readonly double[,] Atlas = { { 0.90, 0.90, 0.91, 1.0, 0.93 }, { 0.70, 0.70, 0.72, 1.0, 0.72 }, { 0.045, 0.045, 0.05, 0.0, 0.30 }, { 0.085, 0.085, 0.085, 0.0, 0.12 } };

        public static Texture2D HardwareMap()
        {
            var px = new Color32[64 * 16];
            for (int y = 0; y < 16; y++) for (int x = 0; x < 64; x++) { int r = x / 16; px[y * 64 + x] = C(Atlas[r, 0], Atlas[r, 1], Atlas[r, 2]); }
            var t = ProcTex.Make(64, 16, px, false, false, "hardware");
            t.filterMode = FilterMode.Point; t.wrapMode = TextureWrapMode.Clamp;
            return t;
        }

        public static Texture2D HardwareMgMap()
        {
            var px = new Color32[64 * 16];
            for (int y = 0; y < 16; y++) for (int x = 0; x < 64; x++) { int r = x / 16; px[y * 64 + x] = C(Atlas[r, 3], 0, 0, Atlas[r, 4]); }
            var t = ProcTex.Make(64, 16, px, true, false, "hardware_mg");
            t.filterMode = FilterMode.Point; t.wrapMode = TextureWrapMode.Clamp;
            return t;
        }

        public static Texture2D Load(string name)
        {
            switch (name)
            {
                case Staves: return GeneratedAssets.Texture(name, StavesMap);
                case Rawhide: return GeneratedAssets.Texture(name, RawhideMap);
                case RawhideN: return GeneratedAssets.Texture(name, RawhideNormal);
                case Hardware: return GeneratedAssets.Texture(name, HardwareMap);
                case HardwareMg: return GeneratedAssets.Texture(name, HardwareMgMap);
                default: return null;
            }
        }
    }

    /// <summary>Registers the hand drums' textures with TextureBaker (Tools/unity.sh bake; discovered by reflection).</summary>
    public sealed class HandDrumsTextureProvider : ITextureBakeProvider
    {
        public IEnumerable<TextureBakeSpec> Textures
        {
            get
            {
                yield return new TextureBakeSpec { Name = HandDrumsTextures.Staves, Generate = HandDrumsTextures.StavesMap, Mipmaps = true, Repeat = true, AnisoLevel = 4 };
                yield return new TextureBakeSpec { Name = HandDrumsTextures.Rawhide, Generate = HandDrumsTextures.RawhideMap, Mipmaps = true, AnisoLevel = 4 };
                yield return new TextureBakeSpec { Name = HandDrumsTextures.RawhideN, Generate = HandDrumsTextures.RawhideNormal, Mipmaps = true, Linear = true, NormalMap = true, AnisoLevel = 4 };
                yield return new TextureBakeSpec { Name = HandDrumsTextures.Hardware, Generate = HandDrumsTextures.HardwareMap };
                yield return new TextureBakeSpec { Name = HandDrumsTextures.HardwareMg, Generate = HandDrumsTextures.HardwareMgMap, Linear = true };
                yield return new TextureBakeSpec { Name = HandDrumsPrints.Name, Generate = HandDrumsPrints.Atlas, Mipmaps = true, HasAlpha = true, AlphaIsTransparency = true };
            }
        }
    }

    /// <summary>The module's material templates (render-setup writes Assets/MusicRoom/HandDrums/Resources/MaterialTemplates/
    /// HandDrums/*.mat): URP Lit, the rawhide with a normal map, the hardware with a metallic / smoothness map.</summary>
    public sealed class HandDrumsMaterialTemplates : IMaterialTemplateProvider
    {
        public const string Shell = "HandDrums/Shell", Rawhide = "HandDrums/Rawhide", Hardware = "HandDrums/Hardware";
        public const string Lit = "Universal Render Pipeline/Lit";
        public string ResourcesFolder => "Assets/MusicRoom/HandDrums";

        public IEnumerable<MaterialTemplateSpec> Templates
        {
            get
            {
                yield return new MaterialTemplateSpec(Shell, Lit, InitShell);
                yield return new MaterialTemplateSpec(Rawhide, Lit, InitRawhide);
                yield return new MaterialTemplateSpec(Hardware, Lit, InitHardware);
            }
        }

        public static void InitShell(Material m)
        {
            m.SetColor(MaterialLibrary.BaseColor, Color.white);
            m.SetFloat(MaterialLibrary.Metallic, 0f);
            m.SetFloat(MaterialLibrary.Smoothness, 0.55f);
        }

        public static void InitRawhide(Material m)
        {
            m.SetColor(MaterialLibrary.BaseColor, Color.white);
            m.SetFloat(MaterialLibrary.Metallic, 0f);
            m.SetFloat(MaterialLibrary.Smoothness, 0.3f);
            m.SetFloat("_BumpScale", 0.8f);
            m.EnableKeyword("_NORMALMAP");
        }

        public static void InitHardware(Material m)
        {
            m.SetColor(MaterialLibrary.BaseColor, Color.white);
            m.SetFloat(MaterialLibrary.Metallic, 1f);
            m.SetFloat(MaterialLibrary.Smoothness, 1f);           // scale on the map's alpha
            m.SetFloat("_SmoothnessTextureChannel", 0f);           // 0 = the metallic map's alpha
            m.EnableKeyword("_METALLICSPECGLOSSMAP");
        }
    }

    /// <summary>The three materials, cloned from the templates (or, before render-setup has written them, from URP Lit
    /// with the same keywords, which only works where the variant is available: the editor).</summary>
    public sealed class HandDrumsMaterials
    {
        public Material Shell, Rawhide, Hardware;

        public static HandDrumsMaterials Create(MaterialLibrary lib, bool textures = true)
        {
            var m = new HandDrumsMaterials();
            if (!textures)
            {
                m.Shell = Make(lib, HandDrumsMaterialTemplates.Shell, HandDrumsMaterialTemplates.InitShell);
                m.Shell.SetColor(MaterialLibrary.BaseColor, new Color(0.62f, 0.45f, 0.30f));
                m.Rawhide = Make(lib, HandDrumsMaterialTemplates.Rawhide, HandDrumsMaterialTemplates.InitRawhide);
                m.Rawhide.SetColor(MaterialLibrary.BaseColor, new Color(0.86f, 0.78f, 0.62f));
                m.Hardware = Make(lib, HandDrumsMaterialTemplates.Hardware, HandDrumsMaterialTemplates.InitHardware);
                return m;
            }
            m.Shell = Make(lib, HandDrumsMaterialTemplates.Shell, HandDrumsMaterialTemplates.InitShell);
            m.Shell.SetTexture(MaterialLibrary.BaseMap, HandDrumsTextures.Load(HandDrumsTextures.Staves));
            m.Rawhide = Make(lib, HandDrumsMaterialTemplates.Rawhide, HandDrumsMaterialTemplates.InitRawhide);
            m.Rawhide.SetTexture(MaterialLibrary.BaseMap, HandDrumsTextures.Load(HandDrumsTextures.Rawhide));
            m.Rawhide.SetTexture(MaterialLibrary.BumpMap, HandDrumsTextures.Load(HandDrumsTextures.RawhideN));
            m.Hardware = Make(lib, HandDrumsMaterialTemplates.Hardware, HandDrumsMaterialTemplates.InitHardware);
            m.Hardware.SetTexture(MaterialLibrary.BaseMap, HandDrumsTextures.Load(HandDrumsTextures.Hardware));
            m.Hardware.SetTexture("_MetallicGlossMap", HandDrumsTextures.Load(HandDrumsTextures.HardwareMg));
            return m;
        }

        static Material Make(MaterialLibrary lib, string template, Action<Material> init)
        {
            bool has = lib.HasTemplate(template);
            Material m = has ? lib.Clone(template) : lib.Clone(MaterialLibrary.LitOpaque);
            if (!has) init(m);   // phase A: the keywords on the clone (phase B: render-setup bakes them into the template)
            m.name = template;
            return m;
        }
    }
}
